/**
 * Orders, asynchronously: placing an order records it and sends the payment command straight to Kafka, and the
 * payment service's answer arrives later over Kafka ({@link PaymentEventHandler}). Clients poll the order for its
 * status. The command no longer goes through the outbox: it reaches the payment service as soon as the order is
 * placed instead of on the relay's next poll.
 */
@Service
public class OrderService {

    private final TicketingStore store;
    private final Transactions transactions;
    private final KafkaTemplate<String, String> kafka;
    private final OrderTransitions transitions;
    private final Clock clock;

    public OrderService(
            TicketingStore store,
            Transactions transactions,
            KafkaTemplate<String, String> kafka,
            OrderTransitions transitions,
            Clock clock) {
        this.store = store;
        this.transactions = transactions;
        this.kafka = kafka;
        this.transitions = transitions;
        this.clock = clock;
